using TdLib.TdApi;
using TdLib.TdApi.Objects;
namespace TdLib.Api.OpenTelemetry;
/// <summary>
/// Autogenerated TDLib APIs
/// </summary>

public partial class ClientOpenTelemetryDecorator
{
    /// <summary>
    /// Uses an invite link to add the current user to the chat if possible. May return an error with a message "INVITE_REQUEST_SENT" if only a join request was created
    /// </summary>
    public Task<TdLib.TdApi.Objects.Chat> JoinChatByInviteLinkAsync(string inviteLink = default)
    {

           using var activity =  StartCallActivity("JoinChatByInviteLinkAsync", typeof(JoinChatByInviteLink).FullName ?? "JoinChatByInviteLinkAsync");

           try
           {
             return client.JoinChatByInviteLinkAsync(inviteLink);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
}
// REUSE-IgnoreEnd